import math

def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

results = {}
N_values = [2, 3, 4]
X_limit = 100

for n in N_values:
    solutions_for_n = []
    # Constraint: x > n, so start from n + 1
    for x in range(n + 1, X_limit + 1):
        LHS = x**n + x
        RHS_target = LHS - 2

        if is_power_of_two(RHS_target):
            k = int(math.log2(RHS_target))
            solutions_for_n.append((x, n, k))

    results[n] = solutions_for_n

print("--- Results ---")
for n, solutions in results.items():
    print(f"N={n}: {solutions}")

