def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

def check_solution(x, n):
    # Calculate LHS: x^n + x
    lhs = x**n + x

    # We need lhs = 2^k + 2, which means lhs - 2 = 2^k
    target = lhs - 2

    if target <= 0:
        return False, None

    if is_power_of_two(target):
        # Find k such that 2^k = target
        k = target.bit_length() - 1
        return True, k
    else:
        return False, None

# Search constraints: n >= 2, x > n. Let's search up to n=5, x=15 for initial test.
N_MAX = 5
X_MAX = 15

solutions = []
for n in range(2, N_MAX + 1):
    for x in range(n + 1, X_MAX + 1):
        is_sol, k = check_solution(x, n)
        if is_sol:
            solutions.append((x, n, k))

print(f"Found solutions: {solutions}")

